            "text": "1. تعريف علم التصنيف (Taxonomy):\nهو العلم الذي يبحث في تشخيص وتسمية وتقسيم الكائنات الحية إلى مجموعات متدرجة ومتجانسة وفق نظام معين بالاعتماد على صفاتها وخصائصها المشتركة.\n\n2. أهداف تصنيف الكائنات الحية:\n- تنظيم وتسهيل دراسة العدد الهائل والمتنوع من الأحياء.\n- حصر وتشخيص الأنواع الحية ومعرفة بيئاتها ومواطنها.\n- الكشف عن صلة القرابة ودرجة الشبه والتطور بين مجموعات الكائنات الحية.\n- مساعدة فروع العلوم الأخرى (كالطب والزراعة والصيدلة والوراثة) في الاستفادة من خصائص الكائنات الحية ومكافحة مسببات الأمراض."
