            "text": "تُرتب الكائنات الحية في سبع مراتب تصنيفية هرمية من الأعم والأشمل إلى الأخص:\n\n1. المملكة (Kingdom): أعلى وأشمل مرتبة تصنيفية، وتضم عدة شعب.\n2. الشعبة (Phylum): تضم عدة أصناف (طوائف) متشابهة في صفات رئيسية.\n3. الصنف / الطائفة (Class): يضم عدة رتب متقاربة.\n4. الرتبة (Order): تضم عدة عوائل (فصائل) متشابهة.\n5. العائلة / الفصيلة (Family): تضم عدة أجناس متقاربة.\n6. الجنس (Genus): يضم نوعاً واحداً أو أكثر من الأنواع شديدة التقارب والشبه.\n7. النوع (Species): أصغر وأدق وحدة أساسية في التصنيف، وتضم الأفراد المتطابقين القادرين على التزاوج الخصب.\n\nقاعدة هرمية ذهبية:\nكلما اتجهنا من المملكة إلى النوع: يقل عدد الأفراد وتزداد درجة التشابه والقرابة."
