            "text": "وضع العلماء عبر التاريخ ثلاثة أنظمة تصنيفية رئيسية:\n\n1. النظام الاصطناعي (Artificial System):\n- أقدم أنظمة التصنيف، اعتمد على الصفات المظهرية الخارجية السطحية مثل الشكل واللون والحجم وطبيعة المعيشة.\n- مثال: تصنيف أرسطو للنباتات (أشجار وشجيرات وأعشاب) والحيوانات (مائية وأرضية وهوائية)، وتصنيف البابليين القدماء.\n\n2. النظام الطبيعي (Natural System):\n- يعتمد على التركيب الداخلي للأعضاء والأنسجة والتشريح، والوظائف الحيوية (الفسيولوجيا)، والتكوين الجنيني، فضلاً عن المظهر الخارجي.\n- يعكس علاقات القرابة الحقيقية بين أفراد المجموعة.\n\n3. النظام التطوري أو النشوئي (Phylogenetic System):\n- يرتب الكائنات الحية في سلم تطوري متدرج يوضح نشوء وتفرع الأجناس والأنواع ودرجة الرقي والتطور عبر العصور الجيولوجية."
