                    "a": "الحل النموذجي:\n1. البدائيات: البكتيريا الكروية، البكتيريا العصوية.\n2. الطليعيات: الأميبا، البراميسيوم (أو اليوغلينا).\n3. الفطريات: فطر البنسيليوم، فطر المشروم (أو عفن الخبز).\n4. النباتات: الفيوناريا، الصنوبر (أو الباقلاء).\n5. الحيوانات: الإسفنج، الأرنب (أو دودة الأرض)."
