            "heading": "النباتات اللا بذرية: الحزازيات وخصائصها (صفحة 44)",
            "diagram_id": "diag_bio_moss_alternation_generations",
            "text": "النباتات اللا بذرية: الحزازيات (Mosses):\n- مجموعة نباتية لاوعائية (لا تمتلك أنسجة وعائية متخصصة للخشب واللحاء)، ولا تمتلك جذوراً ولا سيقاناً ولا أوراقاً حقيقية.\n- صغيرة الحجم (طولها بضعة سنتيمترات) تعيش في الأماكن الرطبة الظليلة.\n- أشهر أمثلتها: الفيوناريا (Funaria).\n- تمر بظاهرة تعاقب الأجيال لإتمام دورة حياتها (طور مشيجي جنسي 1n وطور بوغي لاجنسي 2n)."
