            "text": "السرخسيات (Ferns):\n- نباتات وعائية لا بذرية (تمتلك أنسجة خشب ولحاء متخصصة لنقل الماء والمغذيات).\n- تمتلك جذوراً وسيقاناً أرضية (رايزوم) وأوراقاً ريشية كبيرة تنمو منها.\n- تعيش في الأماكن الظليلة الرطبة، وتتكاثر بالأبواغ المحمولة داخل حافظات أبواغ على السطح السفلي للورقة.\n- يُعدّ الجيل اللاجنسي (البوغي 2n) هو الجيل السائد فيها.\n- أشهر أمثلتها: نبات البوليبوديوم (Polypodium)."
