            "text": "1. خصائص النباتات البذرية (Spermatophyta):\n- أرقى النباتات وأكثرها انتشاراً على الأرض، تتكاثر بالبذور وتمتلك جذراً وساقاً وأوراقاً حقيقية.\n\n2. التركيب النسيجي للورقة:\n- طبقة البشرة العليا والسفلى المغطاة بالكيوتيكل لحماية الورقة وتقليل فقدان الماء، وتحتوي ثغوراً تحرسها خلايا حارسة لتبادل الغازات والنتح.\n- النسيج الوسطي (الميزوفيل): يحتوي على البلاستيدات الخضراء للقيام بالبناء الضوئي.\n- الحزم الوعائية (العروق): تضم الخشب واللحاء."
