            "heading": "شعبة الديدان الخيطية وشعبة الديدان الحلقية (صفحة 58)",
            "diagram_id": "diag_bio_invertebrates_diversity",
            "text": "4. شعبة الديدان الخيطية (Nematoda):\n- ديدان ذات أجسام أسطوانية غير مقسمة لحلقات، ذات تجويف جسمي كاذب وتناظر جانبي.\n- جهازها الهضمي مكتمل يبدأ بالفم وينتهي بفتحة المخرج.\n- مثالها: دودة الأسكارس المتطفلة في الأمعاء.\n\n5. شعبة الديدان الحلقية (Annelida):\n- ديدان يتكون جسمها من حلقات متكررة واضحة، لها تجويف جسمي حقيقي.\n- تمتلك جهاز دوران مغلق وأشواكاً للحركة في التربة أو الماء.\n- مثالها: دودة الأرض ودودة العلق الطبي."
