            "diagram_id": "diag_bio_invertebrates_diversity",
            "text": "6. شعبة المفصليات (Arthropoda):\n- أكبر شعب المملكة الحيوانية وتضم نحو 90% من الأنواع الحيوانية المعروفة.\n- تمتلك زوائد وأرجلاً مفصلية، وهيكلاً خارجياً صلباً من الكايتين.\n- تتنفس بالقصيبات التنفسية (في الحشرات) أو بالخياشيم (في القشريات) أو بالرئات الكتابية (في العناكب والعقارب).\n\n7. شعبة الرخويات (Mollusca):\n- جسمها رخو غير مقسم يحمل صدفة كلسية في الغالب يفرزها البرنس، ولها قدم عضلية (مثل المحار والحلزون والأخطبوط).\n\n8. شعبة شوكيات الجلد (Echinodermata):\n- حيوانات بحرية حصراً، تمتاز بتناظر شعاعي في الطور البالغ وتناظر جانبي في الطور اليرقي، وتتحرك بالأقدام الأنبوبية (مثل نجم البحر)."
