            "text": "1. خصائص الفقريات (شعبة الحبليات):\n- تمتلك هيكلاً داخلياً مؤلفاً من الجمجمة والعمود الفقري والهيكل الطرفي.\n- لها قلب متعدد الردهات وجهاز دوران مغلق، وجهاز هضمي مكتمل، وجلد يتكون من بشرة وأدمة.\n\n2. صنف الأسماك — أولاً: الأسماك الغضروفية:\n- هيكلها الداخلي غضروفي مرن، والفم بطني الموقع، والزعنفة الذيلية متباينة الفصين، وتفتقر للمثانة الهوائية وغطاء الخياشيم (مثل سمك القرش واللخمة)."
