            "text": "5. صنف اللبائن / الثدييات (Mammals):\nحيوانات فقرية ثابتة درجة الحرارة تظهر تنوعاً كبيراً وتكيفات للمعيشة في بيئات مختلفة، وتمتاز بالآتي:\nأ. الجسم مغطى بالشعر بدرجات متفاوتة.\nب. الجلد غني بالغدد مثل الغدد العرقية والدهنية واللبنية.\nج. الهيكل الداخلي عظمي ولها زوجان من الأطراف، وقد تتحور إلى مجاذيف كما في الحيتان.\nد. تمتلك (الحجاب الحاجز Diaphragm) الذي يفصل الجوف الجسمي إلى جزء صدري وآخر بطني.\nهـ. التنفس بالرئتين ذات القوام الإسفنجي لكثرة الحويصلات التنفسية، والقلب من 4 ردهات.\nو. الجهاز الإبرازي يتألف من كليتين وحالبين ومثانة بولية نامية، وهي فقريات ولودة تنمو أجنتها داخل رحم الأم."
