            "text": "1. حالات الكربون في الطبيعة:\n- الحالة الغازية: على شكل غاز ثنائي أوكسيد الكربون (CO₂).\n- الحالة الصلبة: في التربة على هيئة صخور جيرية ووقود أحفوري.\n- الحالة السائلة: على شكل ثنائي أوكسيد الكربون ذائب في الماء.\n\n2. دورة النيتروجين:\nيشكل النيتروجين 78% من الغلاف الجوي، ويُثبّت في التربة على شكل نترات وأمونيا بوساطة البكتيريا (على جذور البقوليات أو في التربة) أو بوساطة البرق، فتستخدمه النباتات لصنع البروتينات ثم ينتقل للحيوانات ويعود للتربة بتحلل الجثث والفضلات."
