            "heading": "دورة النيتروجين ودورة الماء في الطبيعة (صفحة 78 - 79)",
            "diagram_id": "diag_bio_nitrogen_cycle",
            "text": "1. دورة النيتروجين في الطبيعة:\n- يشكل النيتروجين 78% من حجم الهواء، وهو المكون الأساسي لبناء البروتينات والأحماض النووية.\n- تثبيت النيتروجين (Nitrogen Fixation):\n  • التثبيت الحيوي: تقوم به بكتيريا العقد الجذرية (الريزوبيوم) التي تعيش تكافلياً في جذور النباتات البقولية (كالباقلاء والفاصولياء)، حيث تحول النيتروجين الجوي إلى مركبات نترات ذائبة.\n  • التثبيت بالبرق: تؤكسد حرارة شرارة البرق النيتروجين الجوي فيهطل مع المطر كحامض نيتريك مخفف يتحول لنترات في التربة.\n- امتصاص النبات: يمتص النبات النترات لصنع البروتين، وينتقل للحيوان بالتغذية، وعند الموت تحلل بكتيريا التربة الجثث لتطلق النشادر، وتقوم بكتيريا نزع النيتروجين بإعادة الفائض كغاز للجو.\n\n2. دورة الماء (Water Cycle):\n- التبخر والنتح: يتبخر الماء من المسطحات المائية وينتح من ثغور أوراق النباتات بفعل حرارة الشمس.\n- التكاثف والهطول: يرتفع بخار الماء للطبقات العليا فيبرد ويتكاثف مكوناً السحب، ثم يهطل كأمطار وثلوج تعود للأنهار والبحار والمياه الجوفية."
