            "text": "1. موارد البيئة المتجددة (Renewable):\nهي الموارد التي تتجدد باستمرار في الطبيعة ولا تنفد مع الاستغلال الحكيم، مثل ضوء الشمس والهواء والماء والغطاء النباتي.\n\n2. موارد البيئة غير المتجددة (Non-renewable):\nهي الموارد الموجودة بكميات محدودة في باطن الأرض وتُستهلك بمعدل أسرع من تعويضها جيولوجياً، مثل النفط والفحم الحجري والغاز الطبيعي والمعادن."
