            "text": "استراتيجيات حماية الموارد البيئية الثلاث (3Rs):\n1. ترشيد الاستهلاك (Reduce): يُعدّ أهم وسائل حماية الموارد، مثل استخدام الدراجة الهوائية بدلاً من السيارة لتقليل استهلاك الوقود وتلوث الهواء، والامتناع عن شراء المواد غير الضرورية.\n2. إعادة الاستخدام (Reuse): استخدام المواد والأدوات أكثر من مرة دون إجراء عمليات معالجة لها، مثل استخدام حقائب القماش عند التسوق والصحون القابلة للاستعمال المتكرر.\n3. التدوير (Recycle): شكل من أشكال إعادة الاستخدام يحتاج إلى معالجة وإعادة تصنيع بعد الفرز، مثل تدوير الزجاج والمعادن والورق ومخلفات الحدائق."
