            "text": "1. التنوع الأحيائي (Biodiversity):\nتعدد وتنوع الكائنات الحية في البيئة، وكلما زاد التنوع زاد استقرار النظام البيئي.\n\n2. الانقراض والمحميات الطبيعية:\n- تتعرض بعض الأنواع الأصيلة في العراق لخطر الانقراض (مثل أسماك البني والبز في الأنهار العراقية) بسبب الصيد الجائر والتلوث وجفاف المسطحات المائية.\n- المحميات الطبيعية: مواقع تُنشأ قانونياً لحماية النباتات والحيوانات المهددة بالانقراض والحفاظ على التنوع الأحيائي."
