            "text": "علم الأحياء والبيئة — البيئة والتنوع الأحيائي (ص 91):\n- اهتمت الشعوب منذ القدم بالتنوع الأحيائي لحاجتها المباشرة إلى الغذاء واستمرارية الحياة.\n- أصدر الاتحاد العالمي لحماية البيئة في عام 2008م آخر قائمة حمراء للأنواع المهددة بالانقراض (IUCN Red List)، وكشفت أن الحياة على الأرض تختفي بإيقاع متسارع ما لم توضع حلول سريعة ومبتكرة.\n- إحصائيات القائمة الحمراء:\n  • تضم (41,415) نوعاً مهدداً بالانقراض.\n  • سجّلت قائمة الانقراض (785) نوعاً، بينها (65) نوعاً اختفت تماماً من مواطنها الطبيعية ولم تعد موجودة إلا في الأسر والاستزراع.\n  • يداهم خطر الانقراض اليوم (25%) من الثدييات، و(12.5%) من الطيور، و(30%) من البرمائيات، وما يقارب هذه النسبة من الزواحف والأسماك."
