    "details": "• زوائد وأرجل مفصلية مزدوجة متخصصة للمشي أو السباحة أو الطيران.\n• هيكل خارجي صلب من مادة الكايتين يمنع فقدان الماء ويحمى الأعضاء.\n• عيون مركبة وجهاز دوران مفتوح بقلب ظهري، وتشمل الحشرات والقشريات والعناكب."
