    "id": "bio_rule_20",
    "title": "الأسماك العظمية والمثانة الهوائية",
    "category": "مملكة الحيوانات - الفقريات",
    "summary": "أسماك ذات هيكل عظمي وغطاء خيشومي ومثانة سباحة لتعديل الطفو.",
    "details": "• الفم طرفي نهائي، والزعنفة الذيلية متماثلة الفصين.\n• مثانة السباحة: كيس هوائي يمتلئ بالغازات لتعديل الكثافة والصعود والغوص دون إجهاد عضلي.\n• القلب من ردهتين، والجسم مغطى بقشور عظمية دائرية أو مشطية."
