          "2. ما طرائق التكاثر في البراميسيوم؟\nالحل النموذجي:\nيتكاثر بطريقتين: لاجنسياً بالانشطار الثنائي المستعرض، وجنسياً بالاقتران أو الإخصاب المتبادل.",
          "3. كيف تحدث عملية تبادل الغازات في كلٍّ من الأميبا واليوغلينا؟\nالحل النموذجي:\nتحدث عملية تبادل الغازات (التنفس) في كلٍّ منهما عن طريق الانتشار عبر غشاء الخلية (غشاء الجسم).",
          "4. كيف تحصل اليوغلينا على غذائها؟\nالحل النموذجي:\nفي وجود الضوء تصنع غذاءها بنفسها بعملية البناء الضوئي لامتلاكها بلاستيدات خضراء، أما في غياب ضوء الشمس فتتغذى على كائنات حية صغيرة من الأوليات.",
          "5. كيف تتغذى الأميبا؟\nالحل النموذجي:\nتلتقط غذاءها (الأحياء الدقيقة والمواد العضوية) بإحاطته بالأقدام الكاذبة لتكوين فجوة غذائية تفرز عليها الإنزيمات الهاضمة.",
          "1. الهدبيات: مجموعة من الأحياء الأولية تتكاثر بـ (1) .......... و (2) ..........\nالحل النموذجي:\n1. لاجنسياً بالانشطار الثنائي المستعرض.\n2. جنسياً بالاقتران.",
          "2. السوطيات: مجموعة من الأحياء الأولية تمتاز بـ (1) .......... و (2) ..........\nالحل النموذجي:\n1. الحركة بوساطة السوط ووجود البقعة العينية.\n2. امتلاك بلاستيدات خضراء والقدرة على التغذية الذاتية وغير الذاتية (مثالها اليوغلينا).",
