          "1. ما الطبقات الخلوية المكوّنة لنسيج الورقة في النباتات البذرية؟\nالحل النموذجي:\n1. البشرة العليا والبشرة السفلى (المغطاة بطبقة الكيوتيكل وتضم الثغور والخلايا الحارسة).\n2. النسيج الوسطي (المتوسط) الحاوي على البلاستيدات الخضراء.\n3. الأنسجة الوعائية (حزم الخشب واللحاء).",
          "2. قارن بين الأوراق في ذوات الفلقة الواحدة وذوات الفلقتين؟\nالحل النموذجي:\n• ذوات الفلقة الواحدة: أوراقها نحيفة وطويلة ذات تعرق متوازي (مثل الحنطة والنخيل).\n• ذوات الفلقتين: أوراقها عريضة وذات تعرق شبكي متفرع (مثل الباقلاء والبرتقال).",
          "3. ما أهمية أوعية الخشب للنباتات البذرية؟\nالحل النموذجي:\nتنقل الماء والأملاح الذائبة من الجذور صعوداً إلى الساق والأوراق، كما تساعد جدرانها السميكة على توفير الدعم والقوة للنبات.",
          "أكمل المستويات الفارغة في خارطة مفاهيم النباتات (مجموعة الطحالب / مجموعة ...... / مجموعة ......):\nالحل النموذجي:\n• النباتات تنقسم إلى 3 مجموعات رئيسية:\n  1. مجموعة الطحالب.\n  2. مجموعة (النباتات اللابذرية) وتضم: (الحزازيات) و (السرخسيات).\n  3. مجموعة (النباتات البذرية) وتضم: (عاريات البذور) و (مغطاة البذور)؛ ومغطاة البذور تنقسم إلى: (ذوات الفلقة الواحدة) و (ذوات الفلقتين)."
