          "3. شعبة من شعب الحيوانات اللافقرية وتمتاز بأن الجسم فيها ذو تناظر شعاعي في الطور البالغ وتناظر جانبي في الطور اليرقي تسمى ...............\nالحل النموذجي: (شوكية الجلد / شوكيات الجلد).",
